SELECT CAST(DATE(publish_time) AS CHAR) AS day,COUNT(*) AS amount
FROM article_info
WHERE deleted=0 AND status IN (1,2) AND publish_time>=#{start} AND publish_time<#{end}
 AND data_source=#{source}

GROUP BY day

SELECT CAST(DATE(join_time) AS CHAR) AS day,COUNT(*) AS amount
FROM user_info
WHERE join_time>=#{start} AND join_time<#{end}
 AND data_source=#{source}

GROUP BY day
